import React, { useEffect, useState } from 'react';
import API from '../api';
import { useNavigate, Link } from 'react-router-dom';

function Products() {
  const [products, setProducts] = useState([]);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      const res = await API.get('/products/');
      setProducts(res.data);
    } catch (err) {
      setError('Failed to load products');
    }
  };

  const handleOrder = async (productId) => {
    try {
      await API.post('/orders/', { product_id: productId, quantity: 1 });
      alert('Order placed successfully!');
      navigate('/orders');
    } catch (err) {
      alert(err.response?.data?.detail || 'Failed to place order');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  return (
    <div style={styles.container}>
      <div style={styles.navbar}>
        <h2 style={styles.logo}>🛒 Ecommerce</h2>
        <div>
          <Link to="/orders" style={styles.navLink}>My Orders</Link>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </div>

      <div style={styles.body}>
        <h3 style={styles.heading}>All Products</h3>
        {error && <p style={styles.error}>{error}</p>}
        {products.length === 0 && !error && <p>No products found.</p>}
        <div style={styles.grid}>
          {products.map((p) => (
            <div key={p.id} style={styles.card}>
              <h4 style={styles.productName}>{p.name}</h4>
              <p style={styles.desc}>{p.description}</p>
              <p style={styles.price}>${p.price}</p>
              <p style={styles.stock}>In Stock: {p.stock}</p>
              <button
                style={styles.orderBtn}
                onClick={() => handleOrder(p.id)}
                disabled={p.stock === 0}
              >
                {p.stock === 0 ? 'Out of Stock' : 'Order Now'}
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', background: '#f0f2f5' },
  navbar: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#fff', padding: '15px 30px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' },
  logo: { margin: 0 },
  navLink: { marginRight: '20px', color: '#2196F3', textDecoration: 'none', fontWeight: 'bold' },
  logoutBtn: { padding: '8px 16px', background: '#f44336', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer' },
  body: { padding: '30px' },
  heading: { marginBottom: '20px', fontSize: '22px' },
  error: { color: 'red' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '20px' },
  card: { background: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' },
  productName: { margin: '0 0 8px', fontSize: '18px' },
  desc: { color: '#666', fontSize: '14px' },
  price: { fontWeight: 'bold', fontSize: '18px', color: '#4CAF50' },
  stock: { fontSize: '13px', color: '#999' },
  orderBtn: { width: '100%', padding: '10px', background: '#2196F3', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '15px', marginTop: '10px' },
};

export default Products;
